function minCapacity(weights, days) {
  let lo = Math.max(...weights)
  let hi = weights.reduce((a, b) => a + b, 0)
  const need = (cap) => {
    let d = 1
    let cur = 0
    for (const w of weights) {
      if (cur + w > cap) {
        d++
        cur = 0
      }
      cur += w
    }
    return d
  }
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2)
    if (need(mid) <= days) hi = mid
    else lo = mid + 1
  }
  return lo
}

